clock_adapted.manifest:
[package]
name = "browser-gotatun-adapted-probe"
version = "0.0.0"
edition = "2021"
[workspace]
[lib]
crate-type = ["rlib"]
[dependencies]
wg = { package = "gotatun", version = "=0.9.2", default-features = false, features = ["ring"] }
getrandom = { version = "0.2", features = ["js"] }
ring = { version = "0.17", features = ["wasm32_unknown_unknown_js"] }
getrandom03 = { package = "getrandom", version = "0.3", features = ["wasm_js"] }

[patch.crates-io]
gotatun = { path = "<probe-root>/gotatun-clock-adapted" }

patches.src/sleepyinstant/mod.rs:
--- upstream/src/sleepyinstant/mod.rs
+++ experimental/src/sleepyinstant/mod.rs
@@ -89,3 +89,7 @@
         assert!(start.elapsed() >= sleep_time);
     }
 }
+
+// Research-only browser clock adapter.
+#[cfg(target_arch = "wasm32")]
+use web_time as inner;

patches.src/noise/handshake.rs:
--- upstream/src/noise/handshake.rs
+++ experimental/src/noise/handshake.rs
@@ -24,7 +24,11 @@
 use chacha20poly1305::XChaCha20Poly1305;
 use constant_time_eq::constant_time_eq_n;
 use std::convert::TryInto;
-use std::time::{Duration, SystemTime};
+use std::time::Duration;
+#[cfg(not(target_arch = "wasm32"))]
+use std::time::SystemTime;
+#[cfg(target_arch = "wasm32")]
+use web_time::SystemTime;
 use zerocopy::IntoBytes;

 #[cfg(feature = "mock_instant")]

